WGG_st.name='WGG';
WGG_st.lat=-26.570146;
WGG_st.lon=26.939311;
WGG_st.alt=1480;
WGG_st.env='con' %[output:20aa73e8]
WGG_st.footp='RB' %[output:5c389687]
%%
% no RH but should be no problem since dried < 40°
% data imported via import tool
%%
t=(Welgegund_absoprtion_scattering_201109_202601{:,1:6});
WGG_rd=timetable(datetime((t)));
WGG_rd.BaR_A=Welgegund_absoprtion_scattering_201109_202601{:,'Var7'};
WGG_rd.BsB_S=Welgegund_absoprtion_scattering_201109_202601{:,'Var8'};
WGG_rd.BsG_S=Welgegund_absoprtion_scattering_201109_202601{:,'Var9'};
WGG_rd.BsR_S=Welgegund_absoprtion_scattering_201109_202601{:,'Var10'};
namesOK=fieldnames(WGG_rd);
C=startsWith(namesOK,'B');
     N=namesOK(C);
    for i=1:length(N)
         ind=WGG_rd.(N{i})==-999;
     WGG_rd.(N{i})(ind)=NaN;
    end
%%
datevec(WGG_rd.Time(1)) % Sept 2011 --> start 2012 %[output:4beeeff1]
datevec(WGG_rd.Time(end)) % 2025 %[output:3c99d584]
%prctile(WGG_rd.U_S11,[5 50 95])
plotFigControl(WGG_rd,WGG_st.name); %[output:97860848] %[output:4435f63d] %[output:51fc1bc2] %[output:819b7215]
%%
% scattering and absorption statistical BP detection
names_sc={'BsB_S', 'BsG_S', 'BsR_S'};
break_WGG_scat_BP=change_point_analysis_Def(WGG_rd,names_sc,0.05,'WGG','scattering'); %[output:6c8c3dd1] %[output:6e13ed81] %[output:91a3e42b] %[output:69bae2b7]
T_WGG_scat_BP=make_table_breakpoints_def(break_WGG_scat_BP);

names_abs={'BaR_A'};
break_WGG_abs_BP=change_point_analysis_Def(WGG_rd,names_abs,0.05,'WGG','Absorption'); %[output:299b50f7] %[output:56fd808c]
T_WGG_abs_BP=make_table_breakpoints_def(break_WGG_abs_BP);
%%
lambdaSC=[450;525;635];
lambdaAE=637;
WGG_cal=compute_exp_SSA(WGG_rd,lambdaSC, lambdaAE);
plotFigControl_cal(WGG_cal,WGG_st.name); %[output:41e3b3ea] %[output:0a39f24d]
%%
% scattering exp and SSA statistical BP detection
names_exps={'expS_bg3', 'expS_br3', 'expS_gr3'};
break_WGG_exps_BP=change_point_analysis_Def(WGG_cal,names_exps,0.05,'WGG','scattering exp'); %[output:645d2da3] %[output:2a70e2a9] %[output:1a0af5e3] %[output:3f0cda3f]
T_WGG_exps_BP=make_table_breakpoints_def(break_WGG_exps_BP);

names_SSA={'SSA311'};
break_WGG_SSA_BP=change_point_analysis_Def(WGG_cal,names_SSA,0.05,'WGG','SSA'); %[output:9c22a390] %[output:06795a5b]
T_WGG_SSA_BP=make_table_breakpoints_def(break_WGG_SSA_BP); %[output:15a8daff] %[output:6e29c3c5]
%%
%Questions:
%problems:
%
%%
% data for trend
% begin of data in 2012, end in 2025
WGG_tr=WGG_rd;
WGG_tr.y=year(WGG_tr.Time);
% begin at the beginning of a year: 2012 for abs,
%end: 2025
P=timerange('2012-01-01','2026-01-01');
WGG_tr=WGG_tr(P,:);

% abs change for green wavelenght to compute SSA
WGG_tr.BaG_A=WGG_tr.BaR_A.*(637/550);
WGG_tr.BaR_A=[];
WGG_cal2=compute_exp_SSA(WGG_tr,lambdaSC, lambdaAE);
WGG_tr=outerjoin(WGG_tr, WGG_cal2);

%do not compute trend on B, R and exp with red
WGG_tr.BsB_S=[];
WGG_tr.BsR_S=[];

WGG_tr.expS_br3=[];
WGG_tr.expS_gr3=[];
%%
[WGG_result_MK,WGG_result_LMSlog,WGG_result_LMSlin]=all_trend_STN(WGG_tr,WGG_st); %[output:0a18e761] %[output:6f675329] %[output:17470b35] %[output:63e2c51f] %[output:0c2310a8] %[output:59d6c922] %[output:025eb73f] %[output:7249a572] %[output:16c54849] %[output:6f668b23] %[output:57deacee] %[output:142b8ba9] %[output:9a76255d] %[output:696a6f9c] %[output:4192f253] %[output:4944d62f] %[output:4cd16f40] %[output:74532128] %[output:65017d5b] %[output:79a2c2ea] %[output:70a373fd] %[output:1473993b] %[output:33a356ac] %[output:7cdb3255] %[output:4ac9ddc2] %[output:43f9c358] %[output:98b28b37] %[output:406dba6a] %[output:7717181b] %[output:3398f828] %[output:30441404] %[output:1632a711] %[output:9139a7bd] %[output:972b2b20] %[output:01fce019] %[output:10145f0c]

writetable(WGG_result_MK,'WGG_res_MK.txt'); %, 'delimiter',',' )
writetable(WGG_result_LMSlog,'WGG_res_LMSlog.txt'); 
writetable(WGG_result_LMSlin,'WGG_res_LMSlin.txt'); 
plot_10y_in_two(WGG_result_MK, WGG_st,'y'); %[output:7a9dbaa6] %[output:93725e2f]
%%
% since the SSA trend were positive in 2022, I try to compute the trend for
% 2011-2022 to which season were important
WGG_tr_2022=WGG_tr;
P=timerange('2012-01-01','2023-01-01');
WGG_tr_2022=WGG_tr_2022(P,:);
WGG_st_22=WGG_st;
WGG_st_22.name='WGG22';

[WGG_result22_MK,WGG_result22_LMSlog,WGG_result22_LMSlin]=all_trend_STN(WGG_tr_2022,WGG_st_22); %[output:0b581c34] %[output:2d2e476b] %[output:65fa5376] %[output:4819b908] %[output:926cb90f] %[output:5004d4a5] %[output:54444444] %[output:93ddd47a] %[output:4080b96e] %[output:526bb7aa] %[output:4ec376b7] %[output:163de18e] %[output:79ce3103] %[output:7781fffa] %[output:53d00b60] %[output:1704a2d8] %[output:24a76c97]

